function drawFighter(x,y,face,kind,att=0,flash=false){ctx.save();ctx.translate(x,y);ctx.scale(face||1,1);if(flash&&Math.floor(gameTime*24)%2)ctx.globalAlpha=.5;let enemyKind=kind==='enemy';let main=enemyKind?'#ff8b55':'#2eafff',dark=enemyKind?'#a23c56':'#1752a3',light=enemyKind?'#ffd579':'#8af2ff';let kick=att>.05;ctx.fillStyle='#18234466';ctx.beginPath();ctx.ellipse(0,18,24,11,0,0,Math.PI*2);ctx.fill();
