// torso and belt
rounded(-17,-19,34,32,12,main,'#ffffffaa');rounded(-17,2,34,8,4,dark);ctx.fillStyle='#ffe27a';ctx.beginPath();ctx.arc(0,6,4,0,Math.PI*2);ctx.fill();
