function update(dt){if(mode==='splash'||mode==='home'||mode==='fightover'||mode==='collectover'||mode==='winwait'||paused)return;gameTime+=dt;hero.cool=Math.max(0,hero.cool-dt);hero.attack=Math.max(0,hero.attack-dt);hero.invuln=Math.max(0,hero.invuln-dt);hero.stun=Math.max(0,hero.stun-dt);let d=direction(),speed=mode==='collect'?265:240;if(d.m){hero.face=d.x<-.12?-1:d.x>.12?1:hero.face;hero.vx+=d.x*speed*dt*9;hero.vy+=d.y*speed*dt*9}else{hero.vx*=Math.pow(.001,dt);hero.vy*=Math.pow(.001,dt)}let max=speed*(hero.invuln>0?2.3:1),v=Math.hypot(hero.vx,hero.vy);if(v>max){hero.vx*=max/v;hero.vy*=max/v}
if(mode==='collect'){hero.x=clamp(hero.x+hero.vx*dt,60,world.w-60);hero.y=clamp(hero.y+hero.vy*dt,70,world.h-60);cam.x=clamp(hero.x-W/2,0,world.w-W);cam.y=clamp(hero.y-H/2,0,world.h-H);timeLeft-=dt;$('#timeLeft').textContent=Math.max(0,Math.ceil(timeLeft));
