if(timeLeft<=0)loseCollect();
}else if(mode==='fight'){
hero.x=clamp(hero.x+hero.vx*dt,70,W-70);hero.y=clamp(hero.y+hero.vy*dt,H*.51,H*.83);if(enemy.stun>0)enemy.stun-=dt;enemy.cool=Math.max(0,enemy.cool-dt);enemy.attack=Math.max(0,enemy.attack-dt);let dx=hero.x-enemy.x,dy=hero.y-enemy.y,dist=Math.hypot(dx,dy);enemy.face=dx<0?-1:1;if(enemy.stun<=0){if(dist>62){enemy.x+=dx/dist*125*dt;enemy.y+=dy/dist*90*dt}else if(enemy.cool<=0){enemy.attack=.32;enemy.cool=1.05;setTimeout(()=>{if(mode==='fight'&&Math.hypot(hero.x-enemy.x,hero.y-enemy.y)<94&&hero.invuln<=0){hero.health=Math.max(0,hero.health-9);hero.stun=.16;sfx('hit');$('#heroHealth').style.width=hero.health+'%';if(hero.health<=0)endFight(false)}},180)}}
if(Math.abs(hero.x-enemy.x)<39&&Math.abs(hero.y-enemy.y)<35&&hero.invuln<=0){hero.x+=Math.sign(hero.x-enemy.x||1)*90*dt;hero.vx+=Math.sign(hero.x-enemy.x||1)*50*dt}
$('#enemyHealth').style.width=enemy.health+'%';}
if(performance.now()>toastUntil)$('#toast').classList.remove('show')}
function frame(now){let dt=Math.min(.035,(now-last)/1000||0);last=now;update(dt);ctx.clearRect(0,0,W,H);if(mode==='splash'||mode==='home'||mode==='winwait'||mode==='collectover'||mode==='fightover'){drawCover()}else if(mode==='fight'){drawFight()}else{drawWorld()}requestAnimationFrame(frame)}
requestAnimationFrame(frame);startIntro();
})();
